"Login then cashier": {de:"Login dann Kasse",ru:"Сначала вход, потом касса",uk:"Спочатку вхід, потім каса",pl:"Najpierw logowanie, potem kasa",es:"Login luego caja",pt:"Login depois caixa",fr:"Login puis caisse",it:"Login poi cassa",tr:"Önce giriş sonra kasa",nl:"Eerst login dan kassa"},
